package net.civeira.phylax.features.notification.smtpoutboundconfig.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class UseTlsVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property use tls of smtp outbound config ")
  void test_use_tls_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> UseTlsVO.tryFrom(null));
    Assertions.assertEquals(true, UseTlsVO.from(true).isUseTls());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> UseTlsVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + true + "]", UseTlsVO.from(true).toString());
  }
}
